JS_HELPERS = '\nif(typeof JSON===\'undefined\'){JSON={};JSON.stringify=function(v){if(v===null)return \'null\';var t=typeof v;if(t===\'string\')return \'"\'+v.replace(/\\\\/g,\'\\\\\\\\\').replace(/"/g,\'\\\\"\').replace(/\\r/g,\'\\\\r\').replace(/\\n/g,\'\\\\n\').replace(/\\t/g,\'\\\\t\')+\'"\';if(t===\'number\'||t===\'boolean\')return String(v);if(v instanceof Array){var a=[];for(var i=0;i<v.length;i++)a.push(JSON.stringify(v[i]));return \'[\'+a.join(\',\')+\']\';}if(t===\'object\'){var a=[];for(var k in v)if(v.hasOwnProperty(k))a.push(JSON.stringify(k)+\':\'+JSON.stringify(v[k]));return \'{\'+a.join(\',\')+\'}\';}return \'null\';};}\nfunction audit(d){var a={paths:d.pathItems.length,texts:d.textFrames.length,groups:d.groupItems.length,raster:d.rasterItems.length,placed:d.placedItems.length,mesh:d.meshItems.length,gradients:d.gradients.length,nodes:0,gradientFills:0};for(var i=0;i<d.pathItems.length;i++){var p=d.pathItems[i];a.nodes+=p.pathPoints.length;try{if(p.filled&&p.fillColor.typename==\'GradientColor\')a.gradientFills++;}catch(e){}}return a;}\nfunction exports(d,stem){var ao=new IllustratorSaveOptions();ao.pdfCompatible=true;ao.compatibility=Compatibility.ILLUSTRATOR17;ao.compressed=false;d.saveAs(new File(stem+\'.ai\'),ao);var po=new ExportOptionsPNG24();po.artBoardClipping=true;po.transparency=false;po.horizontalScale=100;po.verticalScale=100;po.antiAliasing=true;d.exportFile(new File(stem+\'.png\'),ExportType.PNG24,po);var so=new ExportOptionsSVG();so.embedRasterImages=false;so.embedAllFonts=false;so.fontType=SVGFontType.SVGFONT;so.fontSubsetting=SVGFontSubsetting.GLYPHSUSED;so.coordinatePrecision=3;so.cssProperties=SVGCSSPropertyLocation.PRESENTATIONATTRIBUTES;d.exportFile(new File(stem+\'.svg\'),ExportType.SVG,so);}\nfunction out(v){return JSON.stringify(v);}\nfunction assignNames(d){var used={};var sets=[{items:d.groupItems,prefix:\'vg_\'},{items:d.compoundPathItems,prefix:\'vc_\'},{items:d.pathItems,prefix:\'vp_\'},{items:d.textFrames,prefix:\'vt_\'}];for(var s=0;s<sets.length;s++){var set=sets[s],len=set.items.length;for(var i=0;i<len;i++){var p=set.items[i],n=p.name;if(!n||used[n]){n=set.prefix+(\'000000\'+i).slice(-6);p.name=n;}used[n]=true;}}}\n'
